import RNA, random
sub='(((.((....))((....)).)))'
n=24
# pairs in sub
pairs_sub=[]
st=[]
for i,c in enumerate(sub):
    if c=='(':st.append(i)
    elif c==')':
        j=st.pop();pairs_sub.append((j,i))
print("pairs:",pairs_sub)
comp={'G':'C','C':'G','A':'U','U':'A'}

def fold_ok(seq):
    fc=RNA.fold_compound(seq)
    ss,mfe=fc.mfe()
    return ss==sub

def rand_init():
    seq=['A']*n
    for (i,j) in pairs_sub:
        b=random.choice(['G','C','A','U'])
        seq[i]=b;seq[j]=comp[b]
    return ''.join(seq)

sols=set()
attempts=0
while len(sols)<8 and attempts<200000:
    attempts+=1
    s=rand_init()
    if fold_ok(s):
        sols.add(s)
print("found",len(sols),"sols in",attempts,"attempts")
for s in sols:
    print(s)
EOF
